import sys

def main():
    R = int(sys.stdin.readline().strip())
    total_width = 2 * R

    for i in range(2 * R):
        if i < R:
            left_count = R - i
        else:
            left_count = i - R + 1

        left_stars = '*' * left_count
        spaces = ' ' * (total_width - 2 * left_count)

        if left_count > 0 and left_count < R:
            line = left_stars + spaces + left_stars
        else:
            line = left_stars + spaces

        print(line)

if __name__ == "__main__":
    main()
